import itertools

def calculateCombinations(n, k):
    return len(list(itertools.combinations(range(n), k)))

def distinctBinaryStrings(n, k):
    mod = 10**9 + 7
    # If K is greater than N, any flip operation will not change the string
    if k > n:
        return pow(2, n, mod)

    # If K is 0, all strings are distinct
    if k == 0:
        return pow(2, n, mod)

    uniqueStrings = set()
    # Possible lengths for the binary strings if we flip k characters
    for uniqueLength in range(1, n // 2 + 2):
        for comb in [itertools.combinations(range(uniqueLength), i) for i in range(uniqueLength + 1)]:
            for permutation in itertools.permutations(comb[0]):
                for r in comb:
                    if r in permutation:
                        continue
                    else:
                        perm = permutation + list(permutation.rjust(len(perm), r))
                        perm = map(lambda x: 1 - ord(x) % 2, perm)
                        uniqueStrings.add(''.join(map(str, perm)))

    return len(uniqueStrings) % mod

